#!/usr/bin/env python3
"""Create PNG figures from CSV results generated by the C experiment runner.

Core simulation, WFG construction, DFS/BFS cycle detection, and metrics are
implemented in C. This script only visualizes the exported CSV files.

Inputs:
  results/group_summary.csv       # one averaged row per group / algorithm / K
  results/experiment_results.csv # one averaged row per dataset / algorithm / K

Outputs:
  plots/latency_vs_k_by_group.png
  plots/overhead_vs_k_by_group.png
  plots/frequency_vs_k_by_group.png
  plots/detection_time_by_group_dfs_bfs.png
  plots/overhead_by_group_dfs_bfs.png
  plots/detection_time_vs_edges.png
"""

from __future__ import annotations

import argparse
import csv
import math
import sys
from pathlib import Path
from typing import Iterable

try:
    import matplotlib
    matplotlib.use("Agg")  # WSL/headless-safe backend; must be set before pyplot.
    import matplotlib.pyplot as plt
except ModuleNotFoundError:
    print(
        "Missing matplotlib. In Ubuntu/WSL, install it with:\n"
        "  sudo apt update\n"
        "  sudo apt install python3-matplotlib",
        file=sys.stderr,
    )
    raise SystemExit(1)


GROUP_ORDER = ["small", "medium", "large", "very_large"]
ALGORITHM_ORDER = ["dfs", "bfs"]


def to_float(value: str | None) -> float:
    """Convert CSV text to float; blank values become NaN."""
    try:
        return float(value) if value not in (None, "") else math.nan
    except ValueError:
        return math.nan


def to_int(value: str | None) -> int:
    """Convert a numeric CSV text field to int, with a safe zero fallback."""
    try:
        return int(float(value)) if value not in (None, "") else 0
    except ValueError:
        return 0


def read_results(path: Path) -> list[dict]:
    """Read one result CSV and validate the columns required for plotting."""
    if not path.is_file():
        raise FileNotFoundError(
            f"Missing input file: {path}. Run 'make all' before 'make plot'."
        )

    required_columns = {
        "dataset_group",
        "algorithm",
        "detection_interval",
        "detection_latency",
        "detection_frequency",
        "detection_time_seconds",
        "detection_overhead_seconds",
        "max_wait_for_edges",
    }

    rows: list[dict] = []

    with path.open("r", newline="", encoding="utf-8") as file:
        reader = csv.DictReader(file)
        fields = set(reader.fieldnames or [])
        missing = required_columns - fields

        if missing:
            raise ValueError(
                f"{path} is missing columns: {', '.join(sorted(missing))}"
            )

        for row in reader:
            row["detection_interval"] = to_int(row["detection_interval"])

            for column in (
                "detection_latency",
                "detection_frequency",
                "detection_time_seconds",
                "detection_overhead_seconds",
                "max_wait_for_edges",
            ):
                row[column] = to_float(row[column])

            rows.append(row)

    return rows


def ordered_groups(rows: Iterable[dict]) -> list[str]:
    """Return present groups in the report order."""
    present = {row["dataset_group"] for row in rows}
    known = [group for group in GROUP_ORDER if group in present]
    unknown = sorted(present - set(known))
    return known + unknown


def ordered_algorithms(rows: Iterable[dict]) -> list[str]:
    """Return present algorithms in the report order."""
    present = {row["algorithm"] for row in rows}
    known = [algorithm for algorithm in ALGORITHM_ORDER if algorithm in present]
    unknown = sorted(present - set(known))
    return known + unknown


def save_figure(path: Path) -> None:
    """Save the current Matplotlib figure and close it."""
    plt.tight_layout()
    plt.savefig(path, dpi=300, bbox_inches="tight")
    plt.close()
    print(f"Created: {path}")


def plot_metric_vs_k(
    summary_rows: list[dict],
    metric: str,
    ylabel: str,
    output_path: Path,
    algorithm: str,
) -> None:
    """Plot one line per dataset-scale group for one metric against K.

    The default report version uses DFS here so the latency/overhead trade-off
    is clear and the figure does not become visually crowded.
    """
    selected = [row for row in summary_rows if row["algorithm"] == algorithm]
    groups = ordered_groups(selected)

    if not selected or not groups:
        print(f"Skipped {output_path.name}: no rows for {algorithm.upper()}.")
        return

    plt.figure(figsize=(8, 5))

    for group in groups:
        rows = sorted(
            (row for row in selected if row["dataset_group"] == group),
            key=lambda row: row["detection_interval"],
        )

        x = [row["detection_interval"] for row in rows]
        y = [row[metric] for row in rows]
        plt.plot(x, y, marker="o", label=group)

    plt.xlabel("Detection interval K (events)")
    plt.ylabel(ylabel)
    plt.title(f"{ylabel} vs Detection Interval K ({algorithm.upper()})")
    plt.xticks(sorted({row["detection_interval"] for row in selected}))
    plt.grid(True, alpha=0.3)
    plt.legend(title="Dataset group")

    save_figure(output_path)


def plot_grouped_bar(
    summary_rows: list[dict],
    metric: str,
    ylabel: str,
    output_path: Path,
    k_value: int,
) -> None:
    """Compare DFS and BFS over the four dataset groups at one K value."""
    rows = [
        row
        for row in summary_rows
        if row["detection_interval"] == k_value and not math.isnan(row[metric])
    ]

    groups = ordered_groups(rows)
    algorithms = ordered_algorithms(rows)

    if not rows or not groups or not algorithms:
        print(f"Skipped {output_path.name}: no rows for K={k_value}.")
        return

    lookup = {
        (row["dataset_group"], row["algorithm"]): row[metric]
        for row in rows
    }

    x_positions = list(range(len(groups)))
    bar_width = 0.8 / len(algorithms)

    plt.figure(figsize=(8, 5))

    for index, algorithm in enumerate(algorithms):
        offset = (index - (len(algorithms) - 1) / 2) * bar_width
        values = [lookup.get((group, algorithm), math.nan) for group in groups]
        positions = [position + offset for position in x_positions]

        plt.bar(positions, values, width=bar_width, label=algorithm.upper())

    plt.xlabel("Dataset group")
    plt.ylabel(ylabel)
    plt.title(f"{ylabel} by Dataset Group at K = {k_value}")
    plt.xticks(x_positions, groups)
    plt.grid(axis="y", alpha=0.3)
    plt.legend(title="Algorithm")

    save_figure(output_path)


def plot_detection_time_vs_edges(
    detail_rows: list[dict],
    output_path: Path,
    k_value: int,
) -> None:
    """Plot individual datasets to relate WFG edge count to detection time.

    This is the only plot that uses detailed rows rather than group averages.
    It helps explain non-monotonic cases where a very-large dataset happens to
    take less time than a large dataset due to a sparser graph or early cycle.
    """
    rows = [
        row
        for row in detail_rows
        if row["detection_interval"] == k_value
        and not math.isnan(row["max_wait_for_edges"])
        and not math.isnan(row["detection_time_seconds"])
    ]

    if not rows:
        print(f"Skipped {output_path.name}: no rows for K={k_value}.")
        return

    groups = ordered_groups(rows)
    algorithms = ordered_algorithms(rows)
    markers = ["o", "s", "^", "D", "x", "P"]
    marker_index = 0

    plt.figure(figsize=(8, 5))

    for group in groups:
        for algorithm in algorithms:
            subset = [
                row
                for row in rows
                if row["dataset_group"] == group and row["algorithm"] == algorithm
            ]

            if not subset:
                continue

            plt.scatter(
                [row["max_wait_for_edges"] for row in subset],
                [row["detection_time_seconds"] for row in subset],
                marker=markers[marker_index % len(markers)],
                label=f"{group} / {algorithm.upper()}",
            )
            marker_index += 1

    plt.xlabel("Maximum Wait-for Graph edges")
    plt.ylabel("Average detection time (seconds)")
    plt.title(f"Detection Time vs Wait-for Graph Edges at K = {k_value}")
    plt.grid(True, alpha=0.3)
    plt.legend(fontsize=8, ncol=2)

    save_figure(output_path)


def main() -> None:
    parser = argparse.ArgumentParser(
        description="Plot deadlock experiment results generated by the C implementation."
    )
    parser.add_argument("--results-dir", default="results")
    parser.add_argument("--output-dir", default="plots")
    parser.add_argument(
        "--tradeoff-algorithm",
        default="dfs",
        help="Algorithm used in K trade-off line charts (default: dfs).",
    )
    parser.add_argument(
        "--bar-k",
        type=int,
        default=1,
        help="K value used in DFS/BFS grouped bar charts (default: 1).",
    )
    args = parser.parse_args()

    results_dir = Path(args.results_dir)
    output_dir = Path(args.output_dir)
    output_dir.mkdir(parents=True, exist_ok=True)

    try:
        summary_rows = read_results(results_dir / "group_summary.csv")
        detail_rows = read_results(results_dir / "experiment_results.csv")
    except (FileNotFoundError, ValueError) as error:
        print(f"Plotting failed: {error}", file=sys.stderr)
        raise SystemExit(1)

    # Group-average charts: main evidence for the report.
    plot_metric_vs_k(
        summary_rows,
        metric="detection_latency",
        ylabel="Detection latency (events)",
        output_path=output_dir / "latency_vs_k_by_group.png",
        algorithm=args.tradeoff_algorithm,
    )

    plot_metric_vs_k(
        summary_rows,
        metric="detection_overhead_seconds",
        ylabel="Detection overhead (seconds)",
        output_path=output_dir / "overhead_vs_k_by_group.png",
        algorithm=args.tradeoff_algorithm,
    )

    plot_metric_vs_k(
        summary_rows,
        metric="detection_frequency",
        ylabel="Detection frequency (calls)",
        output_path=output_dir / "frequency_vs_k_by_group.png",
        algorithm=args.tradeoff_algorithm,
    )

    plot_grouped_bar(
        summary_rows,
        metric="detection_time_seconds",
        ylabel="Average detection time (seconds)",
        output_path=output_dir / "detection_time_by_group_dfs_bfs.png",
        k_value=args.bar_k,
    )

    plot_grouped_bar(
        summary_rows,
        metric="detection_overhead_seconds",
        ylabel="Detection overhead (seconds)",
        output_path=output_dir / "overhead_by_group_dfs_bfs.png",
        k_value=args.bar_k,
    )

    # Detailed diagnostic chart: supports the explanation of graph-density effects.
    plot_detection_time_vs_edges(
        detail_rows,
        output_path=output_dir / "detection_time_vs_edges.png",
        k_value=args.bar_k,
    )


if __name__ == "__main__":
    main()
